// Discovery settings (override per run via webhook body).
const c = {
  channel_name: 'Radar Patriota',
  max_age_hours: 72,          // only videos published in the last N hours
  min_duration_s: 240,        // sources shorter than this are skipped (Shorts, teasers)
  long_min_source_s: 1200,    // a long-form cut needs a source of at least 20 min
  max_process_per_run: 2,
  max_uploads_per_day: 5,     // YouTube quota: ~1600 units per upload, 10k/day
  auto_process: true,         // false = classify and record only
  per_source: 15,
};
let body = {};
try { body = $('Webhook').first().json.body || {}; } catch { /* schedule/manual */ }
for (const k of Object.keys(c)) if (body[k] !== undefined) c[k] = typeof c[k] === 'number' ? Number(body[k]) : (typeof c[k] === 'boolean' ? body[k] === true || body[k] === 'true' : body[k]);
return [{ json: { ...c, run_id: `${$execution.id}`, started_at: new Date().toISOString() } }];

// Active subjects from the watchlist table; seeds it on first run.
const rows = $input.all().map((i) => i.json).filter((r) => r.subject_name);
const DEFAULT = [{
  subject_name: 'Lucas Pavanato',
  subject_notes: 'Grafia correta: Pavanato (um T). Deputado federal eleito por São Paulo (PL), ex-vereador.',
  queries: 'Lucas Pavanato, Pavanato',
  channel_urls: 'https://www.youtube.com/@LucasPavanato',
  formats: 'short',
  misspellings: 'Pavanatto',
  active: true,
}];
const split = (s) => String(s || '').split(',').map((x) => x.trim()).filter(Boolean);
const source = rows.length ? rows : DEFAULT;
const subjects = source.filter((r) => r.active !== false && r.active !== 0).map((r) => ({
  subject_name: r.subject_name, subject_notes: r.subject_notes || '', queries: split(r.queries || r.subject_name),
  channels: split(r.channel_urls), formats: String(r.formats || 'short').toLowerCase(), misspellings: split(r.misspellings),
}));
if (!subjects.length) return [];
return [{ json: { subjects, seed: rows.length ? [] : DEFAULT } }];

// New candidates only: not seen before (except DEFERRED), not processed, not ours, plausible length.
const S = $('CONFIG').first().json;
const W = $('WATCHLIST').first().json.subjects;
const res = $('CLIPPER DISCOVER').first().json;
if (!Array.isArray(res?.items)) throw new Error(`DISCOVER_FAILED: ${JSON.stringify(res).slice(0, 300)}`);
const seen = new Map($('LOAD SEEN').all().map((i) => [i.json.video_id, i.json.decision]));
const processed = new Set($('LOAD PROCESSED').all().map((i) => String(i.json.youtube_id || '').split(':')[0]));
const subjectOf = (item) => {
  for (const s of W) {
    if (item.found_by.some((f) => s.queries.some((q) => f === `search:${q}`) || s.channels.some((c) => f === `channel:${c}`))) return s;
  }
  return null;
};
const out = [];
for (const it of res.items) {
  const s = subjectOf(it);
  if (!s || processed.has(it.video_id)) continue;
  const prev = seen.get(it.video_id);
  if (prev && prev !== 'DEFERRED') continue;
  if ((it.channel || '').toLowerCase() === S.channel_name.toLowerCase()) continue;
  if (it.duration != null && it.duration < S.min_duration_s) continue;
  out.push({ ...it, subject_name: s.subject_name, official: it.found_by.some((f) => f.startsWith('channel:')) });
}
console.log(JSON.stringify({ found: res.items.length, new: out.length, errors: res.errors }));
if (!out.length) return [];
return [{ json: { candidates: out.slice(0, 50), ids: out.slice(0, 50).map((c) => c.video_id).join(',') } }];

// Adds publish date / duration / live status from the YouTube API (videos.list = 1 quota unit).
const S = $('CONFIG').first().json;
const { candidates } = $('FILTER NEW').first().json;
const meta = new Map(($input.first().json.items || []).map((v) => [v.id, v]));
const iso = (d) => { const m = String(d || '').match(/P(?:(\d+)D)?T?(?:(\d+)H)?(?:(\d+)M)?(?:(\d+)S)?/) || [];
  return (+m[1] || 0) * 86400 + (+m[2] || 0) * 3600 + (+m[3] || 0) * 60 + (+m[4] || 0); };
const cutoff = Date.now() - S.max_age_hours * 3600 * 1000;
const out = [];
for (const c of candidates) {
  const v = meta.get(c.video_id);
  if (!v) continue;
  if (v.snippet.liveBroadcastContent && v.snippet.liveBroadcastContent !== 'none') continue; // live/upcoming
  const published = new Date(v.snippet.publishedAt);
  const duration = iso(v.contentDetails.duration);
  if (published.getTime() < cutoff || duration < S.min_duration_s) continue;
  out.push({ ...c, title: v.snippet.title, channel: v.snippet.channelTitle, channel_id: v.snippet.channelId,
    published_at: published.toISOString(), duration_s: duration, description: (v.snippet.description || '').slice(0, 600) });
}
console.log(JSON.stringify({ enriched: out.length }));
if (!out.length) return [];
return [{ json: { candidates: out } }];

// Source validation (docs/plan.md §36) for all candidates in one call.
const S = $('CONFIG').first().json;
const W = $('WATCHLIST').first().json.subjects;
const { candidates } = $input.first().json;
const SYSTEM = `Você faz a triagem de fontes do canal editorial independente "${S.channel_name}", que publica
trechos de declarações públicas de: ${W.map((s) => `${s.subject_name} (${s.subject_notes})`).join('; ')}.

Para cada vídeo, classifique:
- source_type: OFFICIAL (canal da própria pessoa), INTERVIEW, PODCAST, NEWS, INSTITUTIONAL (Câmara,
  Senado, partidos, governo), CLIP_CHANNEL (canal de cortes de terceiros), REUPLOAD, UNKNOWN.
- primary_source_probability e reupload_probability: 0–100. Priorize fontes primárias.
- subject_speaks_probability: 0–100, chance de a PESSOA indicada FALAR no vídeo (não só ser assunto).
- recommendation: PROCESS (fonte primária, ele fala, conteúdo com potencial), REVIEW (dúvida) ou IGNORE
  (corte de terceiros, reupload, ele não fala, conteúdo irrelevante).
- reason: uma frase.
Não avalie se concorda politicamente.`;
const schema = { type: 'object', additionalProperties: false, required: ['items'], properties: { items: { type: 'array', items: {
  type: 'object', additionalProperties: false,
  required: ['video_id', 'source_type', 'primary_source_probability', 'reupload_probability', 'subject_speaks_probability', 'recommendation', 'reason'],
  properties: { video_id: { type: 'string' }, source_type: { type: 'string', enum: ['OFFICIAL', 'INTERVIEW', 'PODCAST', 'NEWS', 'INSTITUTIONAL', 'CLIP_CHANNEL', 'REUPLOAD', 'UNKNOWN'] },
    primary_source_probability: { type: 'integer' }, reupload_probability: { type: 'integer' }, subject_speaks_probability: { type: 'integer' },
    recommendation: { type: 'string', enum: ['PROCESS', 'REVIEW', 'IGNORE'] }, reason: { type: 'string' } } } } } };
const list = candidates.map((c) => `- video_id: ${c.video_id}\n  pessoa: ${c.subject_name}\n  título: ${c.title}\n  canal: ${c.channel}${c.official ? ' (canal oficial da pessoa)' : ''}\n  duração: ${Math.round(c.duration_s / 60)} min\n  descrição: ${c.description.replace(/\s+/g, ' ').slice(0, 300)}`).join('\n');
return [{ json: { request: { provider: 'auto', system: SYSTEM, schema, prompt: `VÍDEOS:\n${list}` } } }];

// Policy (docs/plan.md §14) + daily upload cap. Emits one row per candidate for discovered_videos.
const S = $('CONFIG').first().json;
const W = new Map($('WATCHLIST').first().json.subjects.map((s) => [s.subject_name, s]));
const { candidates } = $('ENRICH').first().json;
const res = $input.first().json;
if (!res?.ok || !Array.isArray(res.json?.items)) throw new Error(`${res?.error_code ?? 'LLM_INVALID_JSON'}: source validation ${res?.error_message ?? ''}`);
const v = new Map(res.json.items.map((x) => [x.video_id, x]));

const today = new Date().toLocaleDateString('sv-SE', { timeZone: 'America/Sao_Paulo' });
const usedToday = $('LOAD PROCESSED').all().map((i) => i.json)
  .filter((r) => ['UPLOADED', 'SELECTED', 'PROCESSING'].includes(r.status) && !String(r.youtube_id).endsWith(':dryrun')
    && new Date(r.updated_at).toLocaleDateString('sv-SE', { timeZone: 'America/Sao_Paulo' }) === today).length;
let budget = Math.max(0, Math.min(S.max_process_per_run, S.max_uploads_per_day - usedToday));

const PRIORITY = { OFFICIAL: 0, INTERVIEW: 1, PODCAST: 1, INSTITUTIONAL: 2, NEWS: 3, UNKNOWN: 4 };
const rows = candidates.map((c) => {
  const x = v.get(c.video_id) || { source_type: 'UNKNOWN', recommendation: 'REVIEW', reason: 'sem classificação', subject_speaks_probability: 0 };
  const type = c.official ? 'OFFICIAL' : x.source_type;
  let decision = x.recommendation;
  if (['CLIP_CHANNEL', 'REUPLOAD'].includes(type)) decision = 'IGNORE';
  else if (x.subject_speaks_probability < 50) decision = 'IGNORE';
  else if (['NEWS', 'INSTITUTIONAL', 'UNKNOWN'].includes(type) && decision === 'PROCESS') decision = 'REVIEW';
  const subj = W.get(c.subject_name);
  const wantsLong = /long|both/.test(subj?.formats || '') && c.duration_s >= S.long_min_source_s;
  const wantsShort = /short|both/.test(subj?.formats || 'short');
  const format = wantsShort && wantsLong ? 'both' : wantsLong ? 'long' : 'short';
  return { c, x, type, decision, format, prio: PRIORITY[type] ?? 5 };
});
rows.sort((a, b) => a.prio - b.prio || new Date(b.c.published_at) - new Date(a.c.published_at));
for (const r of rows) {
  if (r.decision !== 'PROCESS') continue;
  const cost = r.format === 'both' ? 2 : 1;
  if (!S.auto_process || budget < cost) { r.decision = 'DEFERRED'; continue; }
  budget -= cost;
}
console.log(JSON.stringify({ usedToday, decisions: rows.map((r) => `${r.c.video_id}:${r.type}:${r.decision}:${r.format}`) }));
return rows.map((r) => ({ json: {
  video_id: r.c.video_id, subject_name: r.c.subject_name, title: r.c.title, channel: r.c.channel, channel_id: r.c.channel_id,
  url: r.c.url, published_at: r.c.published_at, duration_s: r.c.duration_s, source_type: r.type,
  recommendation: r.x.recommendation, decision: r.decision, format: r.format, reason: r.x.reason,
  discovered_at: new Date().toISOString(), run_id: S.run_id,
} }));

// Starts the Short / long-form workflows for PROCESS decisions (webhooks on this same n8n).
const W = new Map($('WATCHLIST').first().json.subjects.map((s) => [s.subject_name, s]));
const out = [];
for (const { json: r } of $('DECIDE').all()) {
  if (r.decision !== 'PROCESS') continue;
  const s = W.get(r.subject_name) || {};
  const base = { source_url: r.url, subject_name: r.subject_name, subject_notes: s.subject_notes || '',
    subject_misspellings: s.misspellings || [], allow_below_threshold: false, upload: true };
  if (r.format !== 'long') out.push({ json: { path: 'pavanato-pilot', body: base } });
  if (r.format !== 'short') out.push({ json: { path: 'radar-longform', body: { ...base, mode: 'best_of', target_minutes: 6 } } });
}
return out;

const rows = $('DECIDE').all().map((i) => i.json);
const by = (d) => rows.filter((r) => r.decision === d).map((r) => `${r.subject_name}: ${r.title} (${r.channel})`);
return [{ json: { run_id: $('CONFIG').first().json.run_id, process: by('PROCESS'), review: by('REVIEW'), deferred: by('DEFERRED'), ignored: by('IGNORE').length } }];
